/**
 * Volunteer Survey Cleaner — Apps Script
 *
 * Assumes:
 *   "Raw" sheet with headers in row 1, data in A2:F(last).
 *     A: Timestamp, B: Name, C: Email,
 *     D: JoinedBefore, E: Phone, F: PreferredPark
 *
 *   "ParkMap" sheet with cols A (lowercase key, no non-alpha) and B (canonical name).
 *
 * Adds helper columns G:P to "Raw" and produces "Review" and "Cleaned" sheets.
 * Never deletes or overwrites columns A:F.
 */

// ─────────────────────────── MENU ───────────────────────────

function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu("Survey Clean")
    .addItem("Run Full Clean", "runFullClean")
    .addItem("Build ParkMap Keys", "buildParkMapKeys")
    .addItem("Export Clean / Review", "exportSheets")
    .addToUi();
}

// ─────────────────────────── MAIN ENTRY POINTS ───────────────────────────

/**
 * Master function: normalises every row, writes helper columns, then exports.
 */
function runFullClean() {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var raw = ss.getSheetByName("Raw");
  if (!raw) { alert_("Sheet 'Raw' not found."); return; }

  var parkMap = loadParkMap_(ss);          // { key: canonical }
  var data    = raw.getDataRange().getValues();  // includes header row
  var last    = raw.getLastRow();
  if (last < 2) { alert_("No data rows in Raw."); return; }

  // ── Write helper headers ──
  var headers = [
    "Norm_YesNo",    // G
    "Norm_Phone",    // H
    "Norm_Timestamp",// I
    "Norm_Park",     // J
    "Key_Email",     // K
    "Key_Name",      // L
    "Flag_DupEmail", // M
    "Flag_DupTime",  // N
    "Superseded",    // O
    "Status"         // P
  ];
  raw.getRange(1, 7, 1, headers.length).setValues([headers]);

  // ── Process each data row ──
  var results = [];          // one array per row, cols G‑P
  var emailIndex = {};       // email → [row indices into results (0‑based)]
  var nameTimeList = [];     // [{name, ts, idx}]

  for (var i = 1; i < data.length; i++) {   // skip header
    var row   = data[i];
    var ts    = row[0];       // Timestamp
    var name  = String(row[1] || "").trim();
    var email = String(row[2] || "").trim();
    var yn    = String(row[3] || "").trim();
    var phone = String(row[4] || "").trim();
    var park  = String(row[5] || "").trim();

    // G – Normalise Yes/No
    var normYN = normaliseYN_(yn);

    // H – Standardise phone
    var normPhone = normalisePhone_(phone);

    // I – Parse timestamp
    var normTS = normaliseTimestamp_(ts);

    // J – Map park
    var normPark = normalisePark_(park, parkMap);

    // K – Email key (lowercase, trimmed)
    var keyEmail = email.toLowerCase();

    // L – Name key (lowercase, collapse whitespace)
    var keyName = name.toLowerCase().replace(/\s+/g, " ");

    results.push([normYN, normPhone, normTS, normPark,
                  keyEmail, keyName,
                  "",   // M placeholder
                  "",   // N placeholder
                  "",   // O placeholder
                  ""    // P placeholder
                 ]);

    // Index for dup detection
    var idx = i - 1;   // index into results[]
    if (keyEmail !== "") {
      if (!emailIndex[keyEmail]) emailIndex[keyEmail] = [];
      emailIndex[keyEmail].push(idx);
    }
    // Only store name‑time entries that have a valid timestamp
    if (normTS instanceof Date) {
      nameTimeList.push({ name: keyName, ts: normTS.getTime(), idx: idx });
    }
  }

  // ── Duplicate flags ──

  // M – DUP-email: any email appearing more than once
  for (var em in emailIndex) {
    if (emailIndex[em].length > 1) {
      emailIndex[em].forEach(function(idx) { results[idx][6] = "DUP-email"; });
    }
  }

  // N – DUP-name-time: same name key within ±10 minutes
  var TEN_MIN_MS = 10 * 60 * 1000;
  // Sort by name then time for efficient pairwise comparison
  nameTimeList.sort(function(a, b) {
    return a.name < b.name ? -1 : a.name > b.name ? 1 : a.ts - b.ts;
  });
  for (var j = 0; j < nameTimeList.length - 1; j++) {
    var cur  = nameTimeList[j];
    var next = nameTimeList[j + 1];
    if (cur.name === next.name && Math.abs(cur.ts - next.ts) <= TEN_MIN_MS) {
      results[cur.idx][7]  = "DUP-name-time";
      results[next.idx][7] = "DUP-name-time";
    }
  }

  // O – SUPERSEDED: within each email group, every row except the most recent
  for (var em2 in emailIndex) {
    var group = emailIndex[em2];
    if (group.length < 2) continue;
    // Find the index with the latest timestamp
    var bestIdx = group[0];
    var bestTS  = tsMillis_(results[bestIdx][2]);
    for (var g = 1; g < group.length; g++) {
      var cand = tsMillis_(results[group[g]][2]);
      if (cand > bestTS) { bestTS = cand; bestIdx = group[g]; }
    }
    group.forEach(function(idx) {
      if (idx !== bestIdx) results[idx][8] = "SUPERSEDED";
    });
  }

  // P – Overall status
  for (var r = 0; r < results.length; r++) {
    var row = results[r];
    var needsReview =
        row[0] === "REVIEW" ||          // G – YN
        row[1] === "REVIEW" ||          // H – Phone
        !(row[2] instanceof Date) ||    // I – Timestamp (string means REVIEW)
        row[3] === "REVIEW" ||          // J – Park
        row[6] !== "" ||                // M – dup email
        row[7] !== "";                  // N – dup name‑time
    row[9] = needsReview ? "REVIEW" : "OK";
  }

  // ── Write helper columns back to Raw (G2:P<last>) ──
  // Convert Date objects back to dates Sheets can display
  var output = results.map(function(row) {
    return row.map(function(cell) {
      return (cell instanceof Date) ? cell : cell;
    });
  });
  raw.getRange(2, 7, output.length, headers.length).setValues(output);

  // Format column I as datetime
  raw.getRange(2, 9, output.length, 1).setNumberFormat("yyyy-mm-dd hh:mm");

  SpreadsheetApp.flush();
  exportSheets();   // auto‑export after cleaning
  alert_("Full clean complete. Check the Review and Cleaned sheets.");
}

// ─────────────────────────── EXPORT ───────────────────────────

/**
 * Creates / refreshes "Review" and "Cleaned" sheets from helper columns.
 */
function exportSheets() {
  var ss  = SpreadsheetApp.getActiveSpreadsheet();
  var raw = ss.getSheetByName("Raw");
  if (!raw) { alert_("Sheet 'Raw' not found."); return; }

  var all     = raw.getDataRange().getValues();
  var headers = all[0];

  var reviewRows  = [headers];
  var cleanedRows = [headers];

  for (var i = 1; i < all.length; i++) {
    var status     = String(all[i][15] || "");  // col P (index 15)
    var superseded = String(all[i][14] || "");  // col O (index 14)
    if (status === "REVIEW") {
      reviewRows.push(all[i]);
    }
    if (status === "OK" && superseded === "") {
      cleanedRows.push(all[i]);
    }
  }

  writeSheet_(ss, "Review", reviewRows);
  writeSheet_(ss, "Cleaned", cleanedRows);

  alert_("Exported " + (reviewRows.length - 1) + " rows to Review, " +
         (cleanedRows.length - 1) + " rows to Cleaned.");
}

// ─────────────────────────── PARKMAP KEY BUILDER ───────────────────────────

/**
 * Scans PreferredPark (col F) for values not yet in ParkMap and
 * appends them as new rows with blank canonical names for the user to fill in.
 */
function buildParkMapKeys() {
  var ss  = SpreadsheetApp.getActiveSpreadsheet();
  var raw = ss.getSheetByName("Raw");
  if (!raw) { alert_("Sheet 'Raw' not found."); return; }

  var pmSheet = ss.getSheetByName("ParkMap");
  if (!pmSheet) {
    pmSheet = ss.insertSheet("ParkMap");
    pmSheet.getRange(1, 1, 1, 2).setValues([["Key", "Canonical"]]);
  }

  var existing = loadParkMap_(ss);  // already‑mapped keys
  var parks = raw.getRange(2, 6, raw.getLastRow() - 1, 1).getValues();

  var unseen = {};
  parks.forEach(function(row) {
    var val = String(row[0] || "").trim();
    if (val === "") return;
    var key = val.replace(/[^a-zA-Z]/g, "").toLowerCase();
    if (key === "") return;
    if (!existing[key] && !unseen[key]) {
      unseen[key] = val;   // keep one raw example
    }
  });

  var keys = Object.keys(unseen);
  if (keys.length === 0) {
    alert_("No new park variants found — ParkMap is up to date.");
    return;
  }

  // Append new keys with blank canonical column
  var append = keys.map(function(k) { return [k, ""]; });
  var nextRow = pmSheet.getLastRow() + 1;
  pmSheet.getRange(nextRow, 1, append.length, 2).setValues(append);

  alert_(keys.length + " new park key(s) added to ParkMap. " +
         "Fill in column B (Canonical) for each, then run Full Clean again.");
}

// ─────────────────────────── NORMALISATION HELPERS ───────────────────────────

/**
 * Normalise a Yes/No value.
 * Accepts y, yes, n, no (case‑insensitive). Everything else → REVIEW.
 */
function normaliseYN_(val) {
  if (val === "") return "REVIEW";
  var v = val.toLowerCase();
  if (/^y(es)?$/.test(v)) return "Yes";
  if (/^no?$/.test(v))    return "No";
  return "REVIEW";
}

/**
 * Strip non‑digits, drop leading country‑code 1,
 * return 10‑digit string or REVIEW.
 */
function normalisePhone_(val) {
  if (val === "") return "REVIEW";
  var digits = val.replace(/\D/g, "");
  if (digits.length === 11 && digits.charAt(0) === "1") {
    digits = digits.substring(1);
  }
  return (digits.length === 10) ? digits : "REVIEW";
}

/**
 * Attempt to parse a timestamp value into a JS Date.
 * Sheets often passes Date objects already; handles strings too.
 * Returns a Date on success, the string "REVIEW" on failure.
 */
function normaliseTimestamp_(val) {
  if (val instanceof Date && !isNaN(val.getTime())) return val;
  if (typeof val === "number") {
    // Sheets serial date number
    var d = new Date((val - 25569) * 86400000);
    if (!isNaN(d.getTime())) return d;
  }
  if (typeof val === "string" && val.trim() !== "") {
    var ms = Date.parse(val);
    if (!isNaN(ms)) return new Date(ms);
  }
  return "REVIEW";
}

/**
 * Map a park string via the ParkMap lookup table.
 * Key = all non‑alpha removed, lowercased.
 */
function normalisePark_(val, parkMap) {
  if (val === "") return "REVIEW";
  var key = val.replace(/[^a-zA-Z]/g, "").toLowerCase();
  if (key === "") return "REVIEW";
  return parkMap[key] || "REVIEW";
}

// ─────────────────────────── UTILITY ───────────────────────────

/**
 * Load ParkMap sheet into a { key: canonical } object.
 */
function loadParkMap_(ss) {
  var sheet = ss.getSheetByName("ParkMap");
  var map = {};
  if (!sheet) return map;
  var rows = sheet.getDataRange().getValues();
  for (var i = 1; i < rows.length; i++) {   // skip header
    var key = String(rows[i][0] || "").trim().toLowerCase();
    var can = String(rows[i][1] || "").trim();
    if (key !== "" && can !== "") map[key] = can;
  }
  return map;
}

/**
 * Create or clear a sheet and write rows (values only).
 */
function writeSheet_(ss, name, rows) {
  var sheet = ss.getSheetByName(name);
  if (sheet) {
    sheet.clearContents();
  } else {
    sheet = ss.insertSheet(name);
  }
  if (rows.length > 0) {
    sheet.getRange(1, 1, rows.length, rows[0].length).setValues(rows);
  }
}

/**
 * Convert a normalised timestamp value to epoch milliseconds for comparison.
 * Returns 0 for non‑Date values so SUPERSEDED logic still works
 * (the row will get REVIEW anyway).
 */
function tsMillis_(val) {
  return (val instanceof Date) ? val.getTime() : 0;
}

/**
 * Simple UI alert wrapper.
 */
function alert_(msg) {
  SpreadsheetApp.getUi().alert(msg);
}
