// ─────────────────────────── SUPERSEDED COMPARISON ───────────────────────────

/**
 * Returns true if candidate (candIdx) is "better" than current best (bestIdx),
 * meaning the candidate should be kept and the other superseded.
 *
 * Logic:
 *   1. If one has a valid timestamp and the other doesn't, the valid one wins.
 *   2. If both have valid timestamps that differ, the earlier or later wins
 *      depending on keepFirst.
 *   3. If timestamps are equal or both invalid, the row's position in the sheet
 *      breaks the tie: higher index (later row) wins when keepFirst=false,
 *      lower index wins when keepFirst=true. (idx is 0‑based row offset.)
 */
function isBetter_(results, candIdx, bestIdx, keepFirst) {
  var candTS = results[candIdx][2];
  var bestTS = results[bestIdx][2];
  var candValid = candTS instanceof Date;
  var bestValid = bestTS instanceof Date;

  // Case: one valid, one not — valid always wins
  if (candValid && !bestValid) return true;
  if (!candValid && bestValid) return false;

  if (candValid && bestValid) {
    var candMs = candTS.getTime();
    var bestMs = bestTS.getTime();
    if (candMs !== bestMs) {
      // keepFirst → smaller ms wins; keepLatest → larger ms wins
      return keepFirst ? (candMs < bestMs) : (candMs > bestMs);
    }
    // Timestamps equal — fall through to row‑number tiebreaker
  }

  // Both invalid or timestamps tied — use row position
  return keepFirst ? (candIdx < bestIdx) : (candIdx > bestIdx);
}

